package com.personal.tasklist;
import static org.junit.Assert.*;
import android.content.*;
import android.app.*;
import java.time.*;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;

@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class ReminderTest {
    Context context;long now;
    @Before public void setup(){context=RuntimeEnvironment.getApplication();context.getSharedPreferences("reference_state",0).edit().clear().commit();TaskReminders.prefs(context).edit().clear().commit();now=LocalDate.of(2026,11,2).atTime(8,0).atZone(ReminderPlanner.ZONE).toInstant().toEpochMilli();}
    JSONObject task()throws Exception{return new JSONObject().put("id","test").put("title","Reminder test").put("due","2026-11-02").put("notify",true).put("time","9:00 AM");}
    @Test public void optInAndTimeAreBothRequired()throws Exception{JSONObject task=task();task.remove("notify");assertEquals(0,ReminderPlanner.next(new JSONArray().put(task),new JSONObject(),now).length());task.put("notify",true).remove("time");assertEquals(0,ReminderPlanner.next(new JSONArray().put(task),new JSONObject(),now).length());}
    @Test public void timeParserSupportsPickerAndLegacyFormats(){assertEquals(LocalTime.of(14,5),ReminderPlanner.time("2:05 PM"));assertEquals(LocalTime.MIDNIGHT,ReminderPlanner.time("12:00 AM"));assertEquals(LocalTime.NOON,ReminderPlanner.time("12:00 PM"));assertEquals(LocalTime.of(23,59),ReminderPlanner.time("23:59"));assertNull(ReminderPlanner.time("Any time"));assertNull(ReminderPlanner.time("24:00"));assertNull(ReminderPlanner.time("13:00 AM"));}
    @Test public void completedTasksAreNotScheduled()throws Exception{JSONObject state=new JSONObject().put("completed",new JSONObject().put("test:2026-11-02",true));assertEquals(0,ReminderPlanner.next(new JSONArray().put(task()),state,now).length());}
    @Test public void movedTaskUsesNewDateAndOriginalCompletionKey()throws Exception{JSONObject state=new JSONObject().put("movedTo",new JSONObject().put("test:2026-11-02","2026-11-03"));JSONObject row=ReminderPlanner.next(new JSONArray().put(task()),state,now).getJSONObject(0);assertEquals("test:2026-11-02",row.getString("key"));assertEquals(LocalDate.of(2026,11,3).atTime(9,0).atZone(ReminderPlanner.ZONE).toInstant().toEpochMilli(),row.getLong("at"));}
    @Test public void repeatedTasksContinueAfterCompletion()throws Exception{JSONObject task=task();task.remove("due");task.put("repeat",new JSONObject().put("amount",1).put("unit","day").put("start","2026-11-02"));JSONObject state=new JSONObject().put("completed",new JSONObject().put("test:2026-11-02",true));assertEquals("2026-11-03",ReminderPlanner.next(new JSONArray().put(task),state,now).getJSONObject(0).getString("date"));}
    @Test public void repeatMonthsClampWithoutDrift()throws Exception{JSONObject task=new JSONObject("{\"repeat\":{\"amount\":1,\"unit\":\"month\",\"start\":\"2026-01-31\"}}");assertTrue(ReminderPlanner.scheduled(task,LocalDate.of(2026,2,28)));assertTrue(ReminderPlanner.scheduled(task,LocalDate.of(2026,3,31)));assertFalse(ReminderPlanner.scheduled(task,LocalDate.of(2026,3,28)));}
    @Test public void weeklyRepeatAndWeekendCycleKeepTheirPhase()throws Exception{JSONObject task=new JSONObject("{\"repeat\":{\"amount\":2,\"unit\":\"week\",\"start\":\"2026-11-01\",\"weekdays\":[0,6]}}");assertFalse(ReminderPlanner.scheduled(task,LocalDate.of(2026,11,7)));assertTrue(ReminderPlanner.scheduled(task,LocalDate.of(2026,11,14)));assertTrue(ReminderPlanner.scheduled(task,LocalDate.of(2026,11,15)));}
    @Test public void editedChecklistUsesStableKeys()throws Exception{JSONObject task=task();task.put("checklistRevisions",new JSONArray("[{\"from\":\"2026-11-02\",\"items\":[{\"key\":\":step:original\",\"title\":\"Step\"}]}]"));JSONObject state=new JSONObject().put("completed",new JSONObject().put("test:2026-11-02:step:original",true));assertTrue(ReminderPlanner.done(task,"2026-11-02",state));}
    @Test public void equalTimeTasksShareTheNextAlarm()throws Exception{JSONObject a=task(),b=task().put("id","second");assertEquals(2,ReminderPlanner.next(new JSONArray().put(a).put(b),new JSONObject(),now).length());}
    @Test public void canonicalOverridesControlOptIn()throws Exception{JSONObject original=task(),changed=task().put("notify",false);JSONObject state=new JSONObject().put("taskOverrides",new JSONObject().put("test",changed));assertEquals(0,ReminderPlanner.next(ReminderPlanner.effective(new JSONArray().put(original),state),state,now).length());}
    @Test public void dailyReminderIsSeparateFromTimedTasks()throws Exception{ReferenceStore store=new ReferenceStore(context);store.writeState("{\"reminders\":{\"daily\":true,\"scheduled\":false}}");TaskReminders.receive(context,TaskReminders.DAILY);assertNotNull(Shadows.shadowOf(context.getSystemService(NotificationManager.class)).getNotification("daily",0));}
    @Test public void turningOffDailyPreventsItsNotification()throws Exception{ReferenceStore store=new ReferenceStore(context);store.writeState("{\"reminders\":{\"daily\":false,\"scheduled\":true}}");TaskReminders.receive(context,TaskReminders.DAILY);assertNull(Shadows.shadowOf(context.getSystemService(NotificationManager.class)).getNotification("daily",0));}
    @Test public void completedTimedTaskDoesNotNotify()throws Exception{JSONObject task=task(),state=new JSONObject().put("customTasks",new JSONArray().put(task)).put("completed",new JSONObject().put("test:2026-11-02",true));new ReferenceStore(context).writeState(state.toString());TaskReminders.prefs(context).edit().putString("next",new JSONArray().put(new JSONObject().put("id","test").put("date","2026-11-02").put("key","test:2026-11-02").put("at",System.currentTimeMillis()-1000)).toString()).commit();TaskReminders.receive(context,TaskReminders.TASK);assertNull(Shadows.shadowOf(context.getSystemService(NotificationManager.class)).getNotification("test:2026-11-02",0));}
    @Test public void bootRestoresDefinitionPlanWithoutOverwritingState()throws Exception{new ReferenceStore(context).writeState("{\"customTasks\":[],\"completed\":{\"keep\":true}}");String before=new ReferenceStore(context).readState();new ReminderReceiver().onReceive(context,new Intent(Intent.ACTION_BOOT_COMPLETED));assertEquals(before,new ReferenceStore(context).readState());assertTrue(TaskReminders.prefs(context).contains("next"));}
}
